import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Scanner;
import java.util.Set;

public class Main {
    record Mark(String code, double mark) {
        Mark {
            if (code.isBlank()) throw new IllegalArgumentException("blank code");
            if (mark < 0 || mark > 10) throw new IllegalArgumentException("bad mark " + mark);
        }
    }

    static String grade(double m) {
        return switch ((int) m) {
            case 10, 9 -> "A";
            case 8, 7 -> "B";
            case 6, 5 -> "C";
            default -> "F";
        };
    }

    static String describe(Object o) {
        if (o instanceof Mark m && m.mark() >= 5) {
            return m.code() + " passed";
        }
        return o + " ignored";
    }

    public static void main(String[] args) {
        var sc = new Scanner(System.in);
        var marks = new ArrayList<Mark>();
        while (sc.hasNextLine()) {
            var line = sc.nextLine().strip();
            if (line.isBlank()) continue;
            String[] p = line.split(";");
            try {
                marks.add(new Mark(p[0].strip(), Double.parseDouble(p[1].strip())));
            } catch (IllegalArgumentException e) {
                System.out.println("skip: " + e.getMessage());
            }
        }
        System.out.println("=".repeat(20));
        for (Mark m : marks) {
            System.out.println(m + " " + grade(m.mark()));
        }
        List<Object> things = List.of(marks.isEmpty() ? "none" : marks.get(0), "text", 42);
        for (Object o : things) {
            System.out.println(describe(o));
        }
        Set<Mark> unique = new LinkedHashSet<>(marks);
        System.out.println("unique marks: " + unique.size());
    }
}

